    scwin.fn_setIem(8, '추가발행수량', 'ISU_SHRS', dtsObj);
    scwin.fn_setIem(9, '유동성공급자', 'LP_MBR_NM', dtsObj);
    scwin.fn_setIem(10, '추가유동성계약일', 'LP_CONTRT_DD', dtsObj);
    scwin.fn_setIem(11, '추가유동성공급개시일', 'LP_STRT_DD', dtsObj);
    scwin.fn_setIem(12, '추가유동성공급종료일', 'LP_END_DD', dtsObj);
};
