scwin.fn_setIem = function(vIdx, strNm, strCd, dtsObj) {
    dts_List.setCellData(vIdx, 'ITEM', strNm);
    dts_List.setCellData(vIdx, 'NEWLIST_REQ', dtsObj.getCellData(1, strCd));
    dts_List.setCellData(vIdx, 'EXEM_REQ', dtsObj.getCellData(2, strCd));
    dts_List.setCellData(vIdx, 'CORRYN', scwin.fn_sameYn(dtsObj.getCellData(1, strCd), dtsObj.getCellData(2, strCd)));
};
scwin.fn_sameYn = function(src1, src2) {
    if (src1 == src2) {
        return 'O';
    } else {
        return 'X';
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    var vHeadString = "ITEM:STRING(100),NEWLIST_REQ:STRING(300),EXEM_REQ:STRING(300),CORRYN:STRING(1)";
    //dts_List.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    var parentWin = $c.frame.path("../");
    var vViewCorrYnTyp = parentWin.vViewCorrYnTyp;
    var dtsObj = parentWin.dts_CorrYn;

    //setObjectValue(txb_ISU_CD, getObjectValue(parentWin.txb_ISU_CD));
    //setObjectValue(txb_ISU_KOR_NM, getObjectValue(parentWin.txb_ISU_KOR_NM));
    $c.stf.setObjectValue(txb_ISU_CD, dtsObj.getCellData(1, 'ISU_CD'));
    $c.stf.setObjectValue(txb_ISU_KOR_NM, dtsObj.getCellData(1, 'ISU_KOR_NM'));
    grd_List.Redraw = false;
    if (vViewCorrYnTyp == '1') {
        // 신규상장
        scwin.fn_setListingData(dtsObj);
    } else if (vViewCorrYnTyp == '2') {
        //추가상장
        scwin.fn_setAddListingData(dtsObj);
    } else if (vViewCorrYnTyp == '3') {
        //신규상장송수신
        $c.cm.setColumnProp(grd_List, "NEWLIST_REQ", "Name", '송신데이타(상장공시)');
        $c.cm.setColumnProp(grd_List, "EXEM_REQ", "Name", '수신데이타(매매)');
        scwin.fn_setSndRcvData(dtsObj);
    }
    grd_List.redraw = true;
    dts_List.setRowPosition(1, 0);
};
